<?php
namespace Tests;
use App\Services\{SalonStore,Tenant,ClientInvitations,Connections,Notifications};
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Crypt,Mail,Http};
final class PersonalizationTest extends TestCase
{
 private string $path;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Külön tesztadatbázis szükséges.');$this->path=storage_path('framework/personalization-'.bin2hex(random_bytes(8)));config(['integrations.path'=>$this->path,'operator.connections_path'=>$this->path.'-platform']);Artisan::call('migrate',['--force'=>true]);foreach(['guest_invitations','deliveries','calendar_tasks','calendar_connections','mail_templates','guest_accounts','salon_state','providers'] as $t)DB::table($t)->delete();DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode(SalonStore::initial())]);Http::preventStrayRequests();$this->admin();}
 protected function tearDown():void{foreach(glob($this->path.'*') as $p)unlink($p);parent::tearDown();}
 private function admin():void{$this->withSession(['admin'=>true,'provider_id'=>1,'guest_id'=>null,'_token'=>str_repeat('t',40)])->withHeader('X-CSRF-TOKEN',str_repeat('t',40));}
 private function guest(int $id=42):void{DB::table('guest_accounts')->insertOrIgnore(['id'=>$id,'name'=>'Google Név','email'=>'account'.$id.'@example.com','provider'=>'google','subject'=>(string)$id,'created_at'=>now(),'updated_at'=>now()]);$this->withSession(['admin'=>false,'guest_id'=>$id]);}
 private function policy(string $p):void{app(SalonStore::class)->mutate(function(&$s)use($p){$s['settings']['guestInvitationPolicy']=$p;});}
 private function client(array $v=[]):array{return $this->postJson('/api/clients',array_replace(['name'=>'Új Vendég','email'=>'new@example.com','phone'=>'06301234567'],$v))->assertCreated()->json();}
 public function test_features_default_off_and_catalog_changes_require_explicit_opt_in():void{$s=app(SalonStore::class)->read();$this->assertFalse($s['settings']['advancedBookingEnabled']);$this->assertFalse($s['settings']['servicePhasesEnabled']);$services=$s['services'];$services[0]['bookingMode']='parallel';$services[0]['capacity']=2;$this->putJson('/api/config',['services'=>$services])->assertUnprocessable();$this->putJson('/api/config',['settings'=>array_replace($s['settings'],['advancedBookingEnabled'=>true]),'services'=>$services])->assertOk();$s=app(SalonStore::class)->read();$this->putJson('/api/config',['settings'=>array_replace($s['settings'],['advancedBookingEnabled'=>false])])->assertOk();$services[0]['name']='Más név';$this->putJson('/api/config',['services'=>$services])->assertOk();$this->assertSame('parallel',app(SalonStore::class)->read()['services'][0]['bookingMode']);}
 public function test_phases_preserved_when_tool_hidden_and_cannot_be_silently_reconfigured():void{$s=app(SalonStore::class)->read();$services=$s['services'];$services[0]['phases']=[15,15,15];$this->putJson('/api/config',['services'=>$services])->assertUnprocessable();$this->putJson('/api/config',['services'=>$services,'settings'=>array_replace($s['settings'],['servicePhasesEnabled'=>true])])->assertOk();$s=app(SalonStore::class)->read();$this->putJson('/api/config',['settings'=>array_replace($s['settings'],['servicePhasesEnabled'=>false]),'services'=>$s['services']])->assertOk();$services[0]['phases']=[10,20,15];$this->putJson('/api/config',['services'=>$services])->assertUnprocessable();}
 public function test_guest_name_and_billing_are_separate_private_and_encrypted():void{$this->guest();$this->patchJson('/api/guest/profile',['name'=>'Saját Név','email'=>'contact@example.com','phone'=>'+36 30 123-4567'])->assertOk();DB::table('guest_accounts')->where('id',42)->update(['name'=>'Friss Google Név']);$this->getJson('/api/guest')->assertOk()->assertJsonPath('name','Saját Név');$data=['name'=>'Számlanév','country'=>'HU','zip'=>'1234','city'=>'Minta','address'=>'Minta 1.','taxNumber'=>'12345678-1-12'];$this->putJson('/api/guest/billing',$data)->assertOk();$this->getJson('/api/guest/billing')->assertJsonPath('name','Számlanév');$this->assertStringNotContainsString('Számlanév',DB::table('guest_accounts')->where('id',42)->value('billing_data'));$this->putJson('/api/guest/billing',['city'=>'Hiányos'])->assertUnprocessable();$this->guest(43);$this->getJson('/api/guest/billing')->assertExactJson([]);$this->admin();$this->getJson('/api/guest/billing')->assertUnauthorized();$this->getJson('/api/public')->assertJsonMissingPath('billing_data')->assertJsonMissingPath('publicFooter');$this->guest();$this->putJson('/api/guest/billing',[])->assertOk();$this->assertNull(DB::table('guest_accounts')->where('id',42)->value('billing_data'));}
 public function test_invitations_off_by_default_and_registered_contact_is_skipped():void{$this->client();$this->assertSame(0,DB::table('guest_invitations')->count());$this->policy('email_first');$this->guest();$this->admin();$this->client(['email'=>'account42@example.com','phone'=>'06201234567']);$this->assertSame(0,DB::table('guest_invitations')->count());DB::table('guest_accounts')->where('id',42)->update(['phone'=>'06309998877']);$this->client(['email'=>'other@example.com','phone'=>'+36309998877']);$this->assertSame(0,DB::table('guest_invitations')->count());}
 public function test_channel_fallback_deduplication_and_real_email_delivery_path():void{$this->policy('email_first');$c=$this->client();$row=DB::table('guest_invitations')->first();$payload=json_decode(Crypt::decryptString($row->payload),true);$this->assertSame('email',$payload['channel']);$this->assertStringNotContainsString('new@example.com',$row->payload);ClientInvitations::queue(app(SalonStore::class)->read(),$c);$this->assertSame(1,DB::table('guest_invitations')->count());app(Connections::class)->save(['smtp_host'=>'smtp.example.invalid','smtp_port'=>587,'mail_from'=>'sender@example.com']);Mail::fake();$result=app(Notifications::class)->run();$this->assertSame(1,$result['sent']);Mail::assertSent(\App\Mail\NotificationMail::class,1);$sms=$this->client(['email'=>'','phone'=>'06201112233']);$fallback=DB::table('guest_invitations')->where('client_id',$sms['id'])->first();$this->assertSame('sms',json_decode(Crypt::decryptString($fallback->payload),true)['channel']);}
 public function test_invitation_requires_link_and_login_and_is_single_owner_provider_scoped():void{$this->policy('email');$c=$this->client();$row=DB::table('guest_invitations')->first();$token=json_decode(Crypt::decryptString($row->payload),true)['token'];$this->postJson('/api/guest/invitations/claim')->assertUnauthorized();$this->guest();$this->postJson('/api/guest/invitations/claim',['token'=>$token])->assertJsonPath('claimed',false);$this->get('/meghivo/'.$token)->assertRedirect('/fiokom?provider=1');$this->postJson('/api/guest/invitations/claim')->assertOk()->assertJsonPath('claimed',true);$this->assertSame(42,app(SalonStore::class)->read()['clients'][0]['guestId']);$this->guest(43);$this->get('/meghivo/'.$token);$this->postJson('/api/guest/invitations/claim')->assertForbidden();$this->assertSame(42,(int)DB::table('guest_invitations')->first()->guest_id);$this->admin();$this->getJson('/api/clients/'.$c['id'].'/billing?provider=2')->assertForbidden();}
 public function test_expired_invitation_and_disabled_sending_never_deliver():void{$this->policy('email');$this->client();$row=DB::table('guest_invitations')->first();$token=json_decode(Crypt::decryptString($row->payload),true)['token'];DB::table('guest_invitations')->where('id',$row->id)->update(['expires_at'=>now()->subDay()]);$this->get('/meghivo/'.$token)->assertRedirect('/fiokom?inviteError=expired');$this->policy('none');$this->assertSame('skipped',ClientInvitations::deliver($row->id,app(SalonStore::class)->read()));}

 public function test_solo_catalog_uses_primary_professional():void{$s=app(SalonStore::class)->read();$this->putJson('/api/config',['settings'=>array_replace($s['settings'],['businessMode'=>'solo','primaryStaffId'=>'anna'])])->assertOk();$new=$s['services'][0];$new['id']='new-solo';$new['staff']=['bence'];$services=[...$s['services'],$new];$this->putJson('/api/config',['services'=>$services])->assertUnprocessable();$services[count($services)-1]['staff']=['anna'];$this->putJson('/api/config',['services'=>$services])->assertOk();}
 public function test_provider_booking_invites_new_client_once_but_public_booking_does_not():void{$this->policy('email');$book=['name'=>'Név','email'=>'book@example.com','phone'=>'06301112233','services'=>['cut'],'staff'=>'anna','start'=>'2035-03-12T09:00:00Z'];$this->postJson('/api/bookings',$book)->assertCreated();$this->assertSame(1,DB::table('guest_invitations')->count());$this->postJson('/api/bookings',array_replace($book,['start'=>'2035-03-13T09:00:00Z']))->assertCreated();$this->assertSame(1,DB::table('guest_invitations')->count());$this->withSession(['admin'=>false]);$this->postJson('/api/bookings',array_replace($book,['email'=>'public@example.com','phone'=>'06304445566','start'=>'2035-03-14T09:00:00Z']))->assertCreated();$this->assertSame(1,DB::table('guest_invitations')->count());}
 public function test_sms_preferred_policy_and_changed_contact_invalidates_pending_link():void{$this->policy('sms_first');$c=$this->client();$row=DB::table('guest_invitations')->first();$payload=json_decode(Crypt::decryptString($row->payload),true);$this->assertSame('sms',$payload['channel']);$this->assertSame('+36301234567',$payload['recipient']);app(SalonStore::class)->mutate(function(&$s){$s['clients'][0]['phone']='06309998877';});$this->assertSame('skipped',ClientInvitations::deliver($row->id,app(SalonStore::class)->read()));$this->guest();$this->get('/meghivo/'.$payload['token']);$this->postJson('/api/guest/invitations/claim')->assertStatus(410);$this->assertEmpty(app(SalonStore::class)->read()['clients'][0]['guestId']??null);}
 public function test_linked_provider_can_prefill_billing_but_other_provider_cannot():void{$this->guest();$this->putJson('/api/guest/billing',['name'=>'Vevő','country'=>'HU','zip'=>'1234','city'=>'Minta','address'=>'Minta 1.'])->assertOk();app(SalonStore::class)->mutate(function(&$s){$s['clients'][]=['id'=>'linked','name'=>'Név','email'=>'','phone'=>'','guestId'=>42];$s['clients'][]=['id'=>'unlinked','name'=>'Név','email'=>'account42@example.com','phone'=>''];});$this->admin();$this->getJson('/api/clients/linked/billing')->assertJsonPath('name','Vevő');$this->getJson('/api/clients/unlinked/billing')->assertNotFound();$this->getJson('/api/clients/linked/billing?provider=2')->assertForbidden();}

 public function test_sms_invitation_uses_central_twilio_and_normalized_recipient():void{$this->policy('sms');$this->client();app(Connections::class)->save(['twilio_sid'=>'ACtest','twilio_token'=>'test-token','twilio_from'=>'+36123456789']);Http::fake(['api.twilio.com/*'=>Http::response(['sid'=>'SMtest'],201)]);$result=app(Notifications::class)->run();$this->assertSame(1,$result['sent']);Http::assertSent(fn($r)=>$r->url()==='https://api.twilio.com/2010-04-01/Accounts/ACtest/Messages.json'&&$r['To']==='+36301234567'&&str_contains($r['Body'],'/meghivo/'));}
}
